SELECT c.* FROM course c
LEFT JOIN user u ON c.teacher_id = u.user_id
c.is_deleted = 0 AND c.status = 1
AND c.category_id = #{categoryId}
AND c.course_type = #{courseType}
AND c.credit >= #{creditMin}
AND c.credit <= #{creditMax}
AND u.real_name LIKE CONCAT('%', #{teacherName}, '%')
AND (c.course_name LIKE CONCAT('%', #{keyword}, '%') OR c.course_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.avg_rating ORDER BY c.selection_count ORDER BY c.credit ORDER BY c.create_time
ASC DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM course c

    LEFT JOIN user u ON c.teacher_id = u.user_id


    c.is_deleted = 0 AND c.status = 1

        AND c.category_id = #{categoryId}


        AND c.course_type = #{courseType}


        AND c.credit >= #{creditMin}


        AND c.credit <= #{creditMax}


        AND u.real_name LIKE CONCAT('%', #{teacherName}, '%')


        AND (c.course_name LIKE CONCAT('%', #{keyword}, '%')
             OR c.course_code LIKE CONCAT('%', #{keyword}, '%'))

SELECT * FROM course
WHERE is_deleted = 0 AND status = 1 AND course_id != #{courseId}
ORDER BY avg_rating DESC, selection_count DESC
LIMIT #{limit}
